type User={id:string;email:string;name:string;role:string;emailVerified:boolean;totpEnabled:boolean;stage?:string};
type Config={preview:boolean;retentionDays:number;maxFileMB:number;currencies:string[];commissions:Record<string,{threshold:number;below:number;above:number}>;minimumWithdrawals:Record<string,number>;legalReady:boolean};
const initialConfig:Config={preview:true,retentionDays:7,maxFileMB:500,currencies:['USD'],commissions:{},minimumWithdrawals:{},legalReady:false};
const money=(n:number,c='USD')=>new Intl.NumberFormat('es-AR',{style:'currency',currency:c}).format((n||0)/100);
function Choice({value,onChange,options,label}:{value:string;onChange:(v:string)=>void;options:string[];label:string}){return <Select value={value} onValueChange={onChange}><SelectTrigger aria-label={label} style={{width:'100%',minHeight:41}}><SelectValue placeholder={label}/></SelectTrigger><SelectContent>{options.map(o=><SelectItem key={o} value={o}>{o}</SelectItem>)}</SelectContent></Select>}
function Field({label,children,help}:{label:string;children:React.ReactNode;help?:string}){return <label className="field"><span>{label}</span>{children}{help&&<small>{help}</small>}</label>}
function Empty({title,text,icon:Icon=Library,action,href}:{title:string;text:string;icon?:any;action?:string;href?:string}){return <div className="empty-state"><Icon size={40}/><h2>{title}</h2><p>{text}</p>{action&&<a className="btn btn-primary" href={href}>{action}<ArrowRight size={16}/></a>}</div>}
function Header({user,dark,toggle}:{user:User|null;dark:boolean;toggle:()=>void}){return <header className="topbar"><a href="/" className="brand" aria-label="Nexo, inicio"><span className="brand-mark">✳</span>nexo<span style={{color:'#ac8fff'}}>.</span></a><nav className="topnav" aria-label="Principal"><a href="/" className="active">Explorar</a><a href="/?filter=Gratis">Proyectos gratis</a><a href="/publicar">Para creadores</a></nav><div className="top-actions"><button className="btn-quiet" onClick={toggle} aria-label={dark?'Activar modo claro':'Activar modo oscuro'}>{dark?<Sun size={18}/>:<Moon size={18}/>}</button>{user?<a href="/biblioteca" className="login-link">Mi biblioteca</a>:<a href="/ingresar" className="login-link">Ingresar</a>}<a href="/publicar" className="btn btn-primary"><Plus size={17}/>Publicar proyecto</a></div></header>}
function Card({p}:{p:Project}){return <article className="project-card"><a className="card-image" href={'/proyecto/'+p.id}><img src={p.image||'/images/code.svg'} alt={p.title} loading="lazy"/><span className="state-badge">{p.status==='Terminado'&&<CheckCircle2 size={10}/>} {p.status}</span></a><div className="card-body"><div className="card-meta"><span>{p.category}</span>{p.reviews>0&&<span className="rating"><Star size={12}/>{p.rating.toFixed(1)}</span>}</div><h3><a href={'/proyecto/'+p.id}>{p.title}</a></h3><p>{p.short}</p><div className="card-tools"><span>{p.tool}</span>{p.tags.filter(t=>t!==p.tool).slice(0,2).map(t=><span key={t}>{t}</span>)}</div><div className="card-footer"><a href={'/vendedor/'+p.sellerId} className="seller"><span className="avatar">{p.seller.split(' ').map(x=>x[0]).join('').slice(0,2)}</span>{p.seller}{p.verified&&<ShieldCheck size={12}/>}</a><span className={'price '+(!p.price?'free':'')}>{p.price?money(p.price):'Gratis'}{p.price>0&&<small>USD</small>}</span></div></div></article>}

export default function Marketplace({path}:{path:string}){
 const [user,setUser]=useState<User|null>(null),[config,setConfig]=useState(initialConfig),[dark,setDark]=useState(true),[ready,setReady]=useState(false);
 useEffect(()=>{const t=localStorage.getItem('nexo-theme')||'dark';setDark(t==='dark');document.documentElement.dataset.theme=t;Promise.all([api('/config'),api('/auth/me')]).then(([c,u])=>{setConfig(c);setUser(u.user)}).catch(()=>{}).finally(()=>setReady(true))},[]);
 const toggle=()=>{const n=!dark;setDark(n);document.documentElement.dataset.theme=n?'dark':'light';localStorage.setItem('nexo-theme',n?'dark':'light')};
 let view:React.ReactNode;
 if(path.startsWith('/proyecto/'))view=<Detail id={path.split('/')[2]} user={user} config={config}/>;
 else if(path==='/publicar')view=<Publish user={user} config={config}/>;
 else if(path==='/ingresar'||path==='/registro'||path==='/seguridad'||path==='/verificar-email'||path==='/recuperar')view=<Auth path={path} config={config} user={user} onUser={setUser}/>;
 else if(path==='/biblioteca')view=<LibraryPage user={user} config={config}/>;
 else if(path==='/saldo')view=<WalletPage user={user} config={config}/>;
 else if(path==='/mis-proyectos')view=<MyProjects user={user} config={config}/>;
 else if(path==='/creador'||path.startsWith('/creador/'))view=<Admin user={user} config={config}/>;
 else if(path==='/terminos'||path==='/privacidad')view=<Legal privacy={path==='/privacidad'}/>;
 else if(path==='/denunciar')view=<CopyrightForm config={config}/>;
 else if(path.startsWith('/vendedor/'))view=<Seller id={path.split('/')[2]} config={config}/>;
 else if(path==='/pago/resultado')view=<PaymentResult user={user}/>;
 else if(path!=='/')view=<div className="page"><Empty title="No encontramos esta página" text="Volvé al catálogo para seguir explorando." action="Explorar proyectos" href="/"/></div>;
 else view=<Catalog config={config}/>;
 return <><Header user={user} dark={dark} toggle={toggle}/>{ready&&config.preview&&<div className="demo-note">Vista previa · Proyectos de muestra. Los registros, las subidas y los pagos todavía no están habilitados.</div>}<main className="container">{user&&<div className="toolbar" style={{paddingTop:18}}><a className="btn btn-quiet" href="/biblioteca"><Library size={15}/>Biblioteca</a>{['SELLER','CREATOR'].includes(user.role)&&<><a className="btn btn-quiet" href="/mis-proyectos">Mis proyectos</a><a className="btn btn-quiet" href="/saldo">Mi saldo</a></>}{user.role==='CREATOR'&&<a className="btn btn-quiet" href="/creador">Panel CREADOR</a>}<button className="btn btn-quiet" onClick={async()=>{await api('/auth/logout','POST');setUser(null);location.href='/'}}><LogOut size={14}/>Salir</button></div>}{view}<footer className="footer"><a href="/" className="brand"><span style={{color:'#a58aff'}}>✳</span>nexo.</a><span>Hecho para quienes crean.</span><div className="footer-links"><a href="/terminos">Términos y condiciones</a><a href="/privacidad">Privacidad</a><a href="/denunciar">Derechos de autor</a><a href="/creador">Administración</a></div></footer></main><Toaster richColors closeButton/></>;
}

function Catalog({config}:{config:Config}){
 const [projects,setProjects]=useState<Project[]>(demoProjects),[q,setQ]=useState(''),[category,setCategory]=useState('Todos'),[sort,setSort]=useState('Destacados'),[filter,setFilter]=useState('Todos'),[status,setStatus]=useState('Todos'),[license,setLicense]=useState('Todas'),[tool,setTool]=useState('Todas'),[min,setMin]=useState(''),[max,setMax]=useState(''),[rating,setRating]=useState('Todas'),[showFilters,setShowFilters]=useState(false),[limit,setLimit]=useState(12),[error,setError]=useState('');
 useEffect(()=>{const p=new URLSearchParams(location.search);if(p.get('filter')==='Gratis')setFilter('Gratis');if(p.get('q'))setQ(p.get('q')!);if(!config.preview)api('/projects').then(r=>setProjects(r.projects)).catch(e=>setError(e.message))},[config.preview]);
 useEffect(()=>{const context=(document as any).modelContext;if(!context?.registerTool)return;const lifecycle=new AbortController();Promise.resolve(context.registerTool({name:'filter_projects',title:'Filtrar proyectos',description:'Actualiza el buscador y la categoría visibles del catálogo. No compra ni descarga.',inputSchema:{type:'object',properties:{query:{type:'string',maxLength:120},category:{type:'string',enum:categories}},additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute:async(input:any)=>{if(!input||typeof input!=='object'||input.query!==undefined&&(typeof input.query!=='string'||input.query.length>120)||input.category!==undefined&&!categories.includes(input.category))throw new Error('Filtros inválidos');setQ(input.query||'');setCategory(input.category||'Todos');await new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r)));return {query:input.query||'',category:input.category||'Todos'};}},{signal:lifecycle.signal})).catch(()=>{});return()=>lifecycle.abort()},[]);
 const results=useMemo(()=>projects.filter(p=>(category==='Todos'||p.category===category)&&(filter==='Todos'||(filter==='Gratis'?p.price===0:p.price>0))&&(status==='Todos'||p.status===status)&&(license==='Todas'||p.license===license)&&(tool==='Todas'||p.tool===tool)&&(!min||p.price>=Number(min)*100)&&(!max||p.price<=Number(max)*100)&&(rating==='Todas'||p.rating>=Number(rating))&&[p.title,p.short,p.tool,p.category,...p.tags].join(' ').toLowerCase().includes(q.toLowerCase())).sort((a,b)=>sort==='Menor precio'?a.price-b.price:sort==='Mayor precio'?b.price-a.price:sort==='Mejor valorados'?b.rating-a.rating:sort==='Más vendidos'?((b as any).sales||0)-((a as any).sales||0):sort==='Recientes'?String(b.createdAt||'').localeCompare(a.createdAt||''):0),[projects,q,category,filter,status,license,tool,min,max,rating,sort]);
 const clear=()=>{setCategory('Todos');setFilter('Todos');setStatus('Todos');setLicense('Todas');setTool('Todas');setMin('');setMax('');setRating('Todas');setQ('')};
 const search=(e:FormEvent)=>{e.preventDefault();document.getElementById('catalogo')?.scrollIntoView({behavior:'smooth',block:'start'});if(!config.preview)api('/search-events','POST',{query:q,results:results.length}).catch(()=>{})};
 const shortcuts=[{name:'Todos',label:'Explorar todo',icon:Grid2X2},{name:'Diseño web / plantillas',label:'Diseño web',icon:Code2},{name:'Juegos 2D',label:'Juegos 2D',icon:Gamepad2},{name:'Juegos 3D',label:'Juegos 3D',icon:Gamepad2},{name:'Modelos 3D',label:'Modelos 3D',icon:Box},{name:'Sprites y pixel art',label:'Pixel art',icon:Palette},{name:'Audio y música',label:'Audio y música',icon:Music2}];
 return <><section className="hero"><div className="hero-copy"><div className="eyebrow"><Sparkles size={14}/>EL PUNTO DE ENCUENTRO PARA CREAR</div><h1>Tu próxima gran idea<br/>empieza <em>acá.</em></h1><p>Explorá proyectos, recursos y herramientas digitales.<br/>Creados por personas como vos.</p><form className="searchbox" onSubmit={search}><Search size={19} className="muted"/><input aria-label="Buscar proyectos" value={q} onChange={e=>setQ(e.target.value)} placeholder="¿Qué vas a crear hoy?" maxLength={120}/><button className="btn btn-primary" type="submit">Explorar<ArrowRight size={15}/></button></form><div className="popular">Probá con:{['Unity','Pixel art','React','Blender'].map(t=><button key={t} onClick={()=>setQ(t)}>{t}</button>)}</div></div><a href={config.preview?"/proyecto/islas-flotantes":"#catalogo"} className="featured"><img src="/images/island.png" alt="Islas flotantes low poly con casas, árboles y cascadas"/><span className="featured-tag"><Sparkles size={12}/>Selección Nexo</span><div className="featured-caption"><div><p>UN MUNDO DE POSIBILIDADES</p><h2>Dejá volar tu próximo proyecto.</h2><p>{config.preview?"Descubrí Skylands · Entornos low poly":"Explorá los proyectos de la comunidad"}</p></div><span className="icon-btn"><ArrowUpRight size={20}/></span></div></a></section><div className="category-strip">{shortcuts.map(({name,label,icon:Icon})=><button key={name} className={'category-pill '+(category===name?'active':'')} onClick={()=>setCategory(name)}><Icon size={16}/>{label}</button>)}<button className="category-pill" onClick={()=>setShowFilters(true)}>Más categorías<Plus size={14}/></button></div><section id="catalogo"><div className="catalog-head"><div><h2 className="section-title">Encontrá algo que te inspire</h2><p className="section-sub">{q||category!=='Todos'||filter!=='Todos'?`${results.length} proyectos encontrados`:'Ideas listas para convertirse en tu próximo proyecto.'}</p></div><div className="catalog-controls"><Choice value={sort} onChange={setSort} label="Ordenar proyectos" options={['Destacados','Recientes','Más vendidos','Menor precio','Mayor precio','Mejor valorados']}/><button className="btn" onClick={()=>setShowFilters(true)}><SlidersHorizontal size={15}/>Filtros</button></div></div>{error&&<div role="alert" className="notice">{error}</div>}{results.length?<div className="project-grid">{results.slice(0,limit).map(p=><Card p={p} key={p.id}/>)}</div>:<Empty title="Todavía no hay coincidencias" text="Probá otra palabra o quitá algunos filtros."/>}{(q||category!=='Todos'||filter!=='Todos')&&<button className="btn btn-quiet" onClick={clear} style={{marginTop:18}}>Limpiar búsqueda y filtros</button>}{results.length>limit&&<div style={{textAlign:'center',marginTop:25}}><button className="btn" onClick={()=>setLimit(x=>x+12)}>Ver más proyectos</button></div>}</section><section className="creator-banner"><UploadCloud size={42} className="banner-icon"/><div style={{flex:1}}><h2>Eso que creaste merece llegar más lejos.</h2><p>Compartí tu talento. Publicá gratis y empezá a vender tus proyectos.</p></div><a href="/publicar" className="btn btn-primary">Quiero publicar<ArrowUpRight size={17}/></a></section><Dialog open={showFilters} onOpenChange={setShowFilters}><DialogContent><DialogTitle>Encontrá tu próximo proyecto</DialogTitle><DialogDescription>Combiná los filtros que te resulten útiles.</DialogDescription><div className="filter-grid"><Field label="Categoría"><Choice value={category} onChange={setCategory} options={categories} label="Categoría"/></Field><Field label="Precio"><Choice value={filter} onChange={setFilter} options={['Todos','Gratis','Pago']} label="Tipo de precio"/></Field><Field label="Estado"><Choice value={status} onChange={setStatus} options={['Todos',...states]} label="Estado"/></Field><Field label="Licencia"><Choice value={license} onChange={setLicense} options={['Todas',...licenses]} label="Licencia"/></Field><Field label="Herramienta"><Choice value={tool} onChange={setTool} options={['Todas',...Array.from(new Set(projects.map(p=>p.tool)))]} label="Herramienta"/></Field><Field label="Valoración mínima"><Choice value={rating} onChange={setRating} options={['Todas','3','4','5']} label="Valoración"/></Field><Field label="Desde (USD)"><input type="number" min="0" value={min} onChange={e=>setMin(e.target.value)}/></Field><Field label="Hasta (USD)"><input type="number" min="0" value={max} onChange={e=>setMax(e.target.value)}/></Field></div><div className="row"><button className="btn btn-quiet" onClick={clear}>Limpiar</button><button className="btn btn-primary" onClick={()=>setShowFilters(false)}>Ver {results.length} proyectos</button></div></DialogContent></Dialog></>;
}

function Detail({id,user,config}:{id:string;user:User|null;config:Config}){
 const [p,setP]=useState<Project|undefined>(demoProjects.find(p=>p.id===id)),[checkout,setCheckout]=useState(false),[accepted,setAccepted]=useState(false),[busy,setBusy]=useState(false),[coupon,setCoupon]=useState(''),[comments,setComments]=useState<any[]>([]),[comment,setComment]=useState(''),[stars,setStars]=useState('5'),[tab,setTab]=useState('Descripción'),[report,setReport]=useState(false),[reason,setReason]=useState(''),[quote,setQuote]=useState<any>(null),[replyTo,setReplyTo]=useState<string|null>(null);
 useEffect(()=>{if(!config.preview){api('/projects/'+id).then(r=>setP(r.project)).catch(()=>setP(undefined));api('/projects/'+id+'/comments').then(r=>setComments(r.comments)).catch(()=>{})}},[id,config.preview]);
 const purchase=async()=>{if(!user){location.href='/ingresar';return}setBusy(true);try{const r=await api('/orders','POST',{projectId:id,coupon,acceptedDeletion:accepted,legalVersion:'2026-09-21'});if(r.free){toast.success('Agregado a tu biblioteca. Descargalo y guardá una copia.');location.href='/biblioteca'}else{const u=new URL(r.approvalUrl);if(!['www.paypal.com','www.sandbox.paypal.com'].includes(u.hostname)||u.protocol!=='https:')throw new Error('Respuesta de pago inválida');location.href=u.href}}catch(e:any){toast.error(e.message)}finally{setBusy(false)}};
 if(!p)return <div className="page"><Empty title="Proyecto no disponible" text="El proyecto pudo haberse eliminado o despublicado." action="Volver al catálogo" href="/"/></div>;
 return <div className="page"><a className="btn btn-quiet" href="/"><ChevronLeft size={16}/>Volver a explorar</a><div className="two-col" style={{marginTop:22}}><div className="stack"><ProjectMedia project={p}/><Tabs value={tab} onValueChange={setTab}><TabsList variant="line"><TabsTrigger value="Descripción">Descripción</TabsTrigger><TabsTrigger value="Detalles">Detalles técnicos</TabsTrigger><TabsTrigger value="Comentarios">Comentarios ({comments.length})</TabsTrigger></TabsList><TabsContent value="Descripción"><div className="panel" style={{marginTop:15}}><h2>Acerca de este proyecto</h2>{p.description.startsWith('<')?<div className="rich-content" dangerouslySetInnerHTML={{__html:p.description}}/>:<p className="detail-description">{p.description}</p>}<div className="divider"/><h2>Referencia e inspiración</h2><p className="muted">{p.reference}</p>{p.demo&&<a className="btn" target="_blank" rel="noopener noreferrer" href={p.demo}>Ver demo<ExternalLink size={14}/></a>}{p.repository&&<a className="btn" target="_blank" rel="noopener noreferrer" href={p.repository}>Repositorio<Code2 size={14}/></a>}</div></TabsContent><TabsContent value="Detalles"><div className="panel" style={{marginTop:15}}><dl className="spec-grid">{Object.entries({'Herramienta':p.tool,'Formatos':p.formats.join(', '),'Versión':p.version,'Licencia':p.license,'Requisitos':p.requirements,'Compatibilidad':p.compatibility}).map(([k,v])=><div key={k}><dt>{k}</dt><dd>{v}</dd></div>)}</dl><div className="divider"/><h2>Historial de cambios</h2><p className="detail-description">{p.changelog}</p>{p.installation&&<><h2>Instalación</h2><p className="detail-description">{p.installation}</p></>}</div></TabsContent><TabsContent value="Comentarios"><div className="panel" style={{marginTop:15}}>{comments.length?comments.map(c=><div key={c.id} style={{marginBottom:22,marginLeft:c.parent_id?20:0}}><div className="row"><strong>{c.author}</strong><button className="btn btn-quiet" onClick={()=>{setReplyTo(c.parent_id||c.id)}}>Responder</button></div><p className="detail-description">{c.body}</p></div>):<p className="muted">Todavía no hay comentarios. Iniciá la conversación.</p>}<div className="divider"/>{replyTo&&<button className="btn btn-quiet" onClick={()=>setReplyTo(null)}>Cancelar respuesta</button>}<form className="stack" onSubmit={async e=>{e.preventDefault();try{await api('/projects/'+id+'/comments','POST',{body:comment,parentId:replyTo});setComment('');setReplyTo(null);const r=await api('/projects/'+id+'/comments');setComments(r.comments);toast.success('Comentario publicado')}catch(e:any){toast.error(e.message)}}}><Field label={replyTo?'Tu respuesta':'Tu comentario'}><textarea value={comment} onChange={e=>setComment(e.target.value)} required maxLength={3000} placeholder="Compartí tu experiencia o hacé una pregunta"/></Field><button className="btn btn-primary" disabled={!user||config.preview}>Publicar comentario</button></form><div className="divider"/><div className="row"><Choice value={stars} onChange={setStars} options={['1','2','3','4','5']} label="Estrellas"/><button className="btn" disabled={!user||config.preview} onClick={async()=>{try{await api('/projects/'+id+'/rating','PUT',{rating:Number(stars)});toast.success('Valoración guardada')}catch(e:any){toast.error(e.message)}}}>Calificar</button></div><p className="muted" style={{fontSize:12,marginTop:10}}>Solo pueden calificar quienes compraron o descargaron el proyecto.</p></div></TabsContent></Tabs></div><aside className="stack sticky-panel"><div><div className="eyebrow">{p.category}</div><h1 className="detail-title">{p.title}</h1><p className="muted" style={{margin:'14px 0',lineHeight:1.6}}>{p.short}</p><span className="state-badge">{p.status}</span></div><div className="panel stack"><div className="row"><span className={'amount '+(!p.price?'free':'')}>{p.price?money(p.price):'Gratis'}</span>{!!p.price&&<span className="muted">USD</span>}</div><div className="row muted" style={{fontSize:14}}><span>Licencia</span><span>{p.license}</span></div><button className="btn btn-primary" onClick={()=>{setCheckout(true);setAccepted(false);setQuote(null)}}>{p.price?'Comprar con PayPal':'Obtener proyecto'}<ArrowRight size={17}/></button><div className="notice"><strong><Download size={15} style={{display:'inline',marginRight:7}}/>Descargalo y guardalo en tu equipo</strong>Si el vendedor elimina este proyecto, sus archivos dejarán de estar disponibles. No conservamos copias del contenido eliminado.</div>{config.preview&&<p className="muted" style={{fontSize:12}}>Proyecto de muestra. No se realizarán cobros.</p>}</div><a href={'/vendedor/'+p.sellerId} className="panel row"><span className="seller"><span className="avatar" style={{width:40,height:40,fontSize:14}}>{p.seller[0]}</span><span style={{color:'var(--foreground)'}}>{p.seller}{p.verified&&<small style={{display:'block',color:'#88d2b7'}}>Vendedor verificado</small>}</span></span><ArrowUpRight size={18}/></a><button className="btn btn-quiet" onClick={()=>setReport(true)}><Flag size={14}/>Reportar proyecto</button>{user?.role==='CREATOR'&&<button className="btn" onClick={async()=>{try{const r=await api('/admin/projects/'+id+'/download','POST',{purpose:'Verificación de integridad'});location.href=r.url}catch(e:any){toast.error(e.message)}}}><ShieldCheck size={16}/>Descarga administrativa</button>}</aside></div><Dialog open={checkout} onOpenChange={setCheckout}><DialogContent><DialogTitle>{p.price?'Antes de comprar':'Antes de descargar'}</DialogTitle><DialogDescription>{p.title}</DialogDescription><div className="notice">{deletionNotice}</div><label className="checkrow"><Checkbox checked={accepted} onCheckedChange={v=>setAccepted(v===true)}/><span>Entiendo la condición de disponibilidad y acepto los <a href="/terminos" target="_blank" style={{textDecoration:'underline'}}>Términos y Condiciones</a>.</span></label>{p.price>0&&<><Field label="Cupón (opcional)"><input value={coupon} onChange={e=>setCoupon(e.target.value.toUpperCase())} maxLength={40}/></Field><button className="btn" disabled={config.preview} onClick={async()=>{try{setQuote(await api('/orders/quote','POST',{projectId:id,coupon}))}catch(e:any){toast.error(e.message)}}}>Aplicar cupón</button></>}<div className="row"><strong>Total</strong><strong>{money(quote?.gross??p.price)}</strong></div>{config.preview?<div className="notice">Esta es una vista previa. Las compras se habilitarán al conectar el servidor y PayPal.</div>:<button className="btn btn-primary" disabled={!accepted||busy} onClick={purchase}>{busy?'Preparando…':!user?'Ingresar para continuar':p.price?'Continuar a PayPal':'Agregar a mi biblioteca'}</button>}</DialogContent></Dialog><Dialog open={report} onOpenChange={setReport}><DialogContent><DialogTitle>Reportar proyecto</DialogTitle><DialogDescription>El CREADOR revisará tu reporte.</DialogDescription><Field label="Motivo"><textarea value={reason} onChange={e=>setReason(e.target.value)} maxLength={3000}/></Field><button className="btn btn-primary" disabled={config.preview||reason.trim().length<10} onClick={async()=>{try{await api('/reports','POST',{projectId:id,reason});setReport(false);toast.success('Reporte recibido')}catch(e:any){toast.error(e.message)}}}>Enviar reporte</button><a href="/denunciar" className="muted">¿Es una denuncia de derechos de autor?</a></DialogContent></Dialog></div>;
}

function Publish({user,config}:{user:User|null;config:Config}){
 const [step,setStep]=useState('Proyecto'),[data,setData]=useState<Record<string,any>>({title:'',short:'',description:'',category:categories[1],subcategory:'General',status:'Terminado',reference:'',tool:'',formats:'',version:'1.0',changelog:'Primera versión.',requirements:'',compatibility:'',license:'Uso personal',customLicense:'',tags:'',price:'0',pricing:'Gratis',currency:'USD',demo:'',repository:'',installation:''}),[file,setFile]=useState<File|null>(null),[images,setImages]=useState<File[]>([]),[video,setVideo]=useState<File|null>(null),[videoUrl,setVideoUrl]=useState(''),[progress,setProgress]=useState(0),[busy,setBusy]=useState(false),[quote,setQuote]=useState<any>(null),[savedId,setSavedId]=useState(''),[savedAssets,setSavedAssets]=useState<any[]>([]);
 useEffect(()=>{const id=new URLSearchParams(location.search).get('edit');if(id&&user&&!config.preview)api('/seller/projects/'+id).then(r=>{const p=r.project;setData({...p,formats:p.formats.join(', '),tags:p.tags.join(', '),price:String(p.price/100),pricing:p.price?'Pago':'Gratis'});setSavedId(id);setVideoUrl(p.videoUrl||'');setSavedAssets(r.assets||[])}).catch(e=>toast.error(e.message))},[user,config.preview]);
 const set=(k:string,v:any)=>setData(d=>({...d,[k]:v}));
 useEffect(()=>{if(config.preview)return;const timer=setTimeout(()=>{api('/seller/quote','POST',{price:Math.round(Number(data.price)*100),currency:data.currency}).then(setQuote).catch(()=>{})},350);return()=>clearTimeout(timer)},[data.price,data.currency,config.preview]);
 const price=data.pricing==='Gratis'?0:Math.round(Number(data.price)*100);const rule=config.commissions.USD;const rate=quote?.rate??(rule?(price<rule.threshold?rule.below:rule.above):null);const fee=rate!==null?Math.round(price*rate/100):0;
 async function upload(f:File,purpose:string,projectId:string){return uploadPrivate(f,purpose,setProgress,projectId)}
 async function save(publish:boolean){if(config.preview){toast.info('La vista previa no guarda proyectos. Completá el recorrido para revisar el formulario.');return}if(!user){location.href='/ingresar';return}setBusy(true);try{if(user.role==='USER')await api('/seller/register','POST');const payload={...data,price,formats:data.formats.split(',').map((s:string)=>s.trim()).filter(Boolean),tags:data.tags.split(',').map((s:string)=>s.trim()).filter(Boolean),videoUrl};const r=await api(savedId?'/seller/projects/'+savedId:'/seller/projects',savedId?'PATCH':'POST',payload);setSavedId(r.id);if(file){await upload(file,'main',r.id);setFile(null)}for(const image of images)await upload(image,'image',r.id);setImages([]);if(video){await upload(video,'video',r.id);setVideo(null)}const assets=await api('/seller/projects/'+r.id+'/assets');setSavedAssets(assets.items);if(publish){await api('/seller/projects/'+r.id+'/publish','POST');toast.success('Proyecto enviado. Estará disponible al completar las verificaciones.')}else toast.success('Borrador guardado');}catch(e:any){toast.error(e.message)}finally{setBusy(false)}}
 const requiredFilled=['title','short','description','reference','tool','formats','requirements','compatibility'].every(k=>String(data[k]).trim());
 return <div className="page"><div className="page-heading"><div className="eyebrow"><UploadCloud size={15}/>TU TALENTO TIENE UN LUGAR</div><h1>Publicá tu próximo proyecto.</h1><p className="muted">Compartí lo que creaste. Elegí cómo ofrecerlo y mantené el control.</p></div><div className="two-col"><div className="stack"><Tabs value={step} onValueChange={setStep}><TabsList><TabsTrigger value="Proyecto">1. Proyecto</TabsTrigger><TabsTrigger value="Archivos">2. Archivos</TabsTrigger><TabsTrigger value="Precio">3. Precio</TabsTrigger></TabsList><TabsContent value="Proyecto"><div className="panel field-grid" style={{marginTop:15}}><div className="full"><Field label="Título *"><input value={data.title} onChange={e=>set('title',e.target.value)} maxLength={120} placeholder="Dale un nombre a tu proyecto"/></Field></div><div className="full"><Field label="Descripción corta *" help={`${data.short.length}/160 caracteres`}><input value={data.short} onChange={e=>set('short',e.target.value)} maxLength={160} placeholder="Qué es y qué lo hace especial"/></Field></div><div className="full"><div className="field"><span>Descripción larga *</span><RichEditor value={data.description} onChange={v=>set('description',v)}/><small>Contá qué incluye, cómo se usa y para quién está pensado.</small></div></div><Field label="Categoría *"><Choice value={data.category} onChange={v=>set('category',v)} options={categories.slice(1)} label="Categoría"/></Field><Field label="Subcategoría *"><input value={data.subcategory} onChange={e=>set('subcategory',e.target.value)}/></Field><Field label="Estado del proyecto *"><Choice value={data.status} onChange={v=>set('status',v)} options={states} label="Estado"/></Field><Field label="Herramienta o motor *"><input value={data.tool} onChange={e=>set('tool',e.target.value)} placeholder="Unity, Godot, Blender, React…"/></Field><div className="full"><Field label="Referencia o inspiración *"><textarea value={data.reference} onChange={e=>set('reference',e.target.value)} placeholder="¿Para qué sirve? ¿En qué te inspiraste?"/></Field></div><Field label="Formatos incluidos *" help="Separados por comas"><input value={data.formats} onChange={e=>set('formats',e.target.value)} placeholder=".fbx, .blend, .png"/></Field><Field label="Versión *"><input value={data.version} onChange={e=>set('version',e.target.value)}/></Field><div className="full"><Field label="Changelog *"><textarea value={data.changelog} onChange={e=>set('changelog',e.target.value)}/></Field></div><Field label="Requisitos técnicos *"><input value={data.requirements} onChange={e=>set('requirements',e.target.value)}/></Field><Field label="Compatibilidad *"><input value={data.compatibility} onChange={e=>set('compatibility',e.target.value)}/></Field><Field label="Licencia *"><Choice value={data.license} onChange={v=>set('license',v)} options={licenses} label="Licencia"/></Field><Field label="Tags *"><input value={data.tags} onChange={e=>set('tags',e.target.value)} placeholder="low poly, entornos, aventura"/></Field>{data.license==='Personalizada'&&<div className="full"><Field label="Condiciones de la licencia *"><textarea value={data.customLicense} onChange={e=>set('customLicense',e.target.value)}/></Field></div>}<Field label="Demo online"><input type="url" value={data.demo} onChange={e=>set('demo',e.target.value)} placeholder="https://…"/></Field><Field label="Repositorio"><input type="url" value={data.repository} onChange={e=>set('repository',e.target.value)} placeholder="https://…"/></Field><div className="full"><Field label="Instrucciones de instalación"><textarea value={data.installation} onChange={e=>set('installation',e.target.value)}/></Field></div><button className="btn btn-primary full" onClick={()=>setStep('Archivos')}>Continuar con archivos<ArrowRight size={15}/></button></div></TabsContent><TabsContent value="Archivos"><div className="panel stack" style={{marginTop:15}}><h2>Mostrá lo que creaste</h2>{savedId&&<AssetManager projectId={savedId} onAssets={setSavedAssets}/>}<Field label={`Archivo principal ZIP o RAR * · Máximo ${config.maxFileMB} MB`}><input type="file" accept=".zip,.rar" onChange={e=>{const f=e.target.files?.[0];if(f&&f.size>config.maxFileMB*1024*1024){toast.error('El archivo supera el límite');e.target.value='';return}setFile(f||null)}}/></Field><Field label="Imágenes de referencia · Hasta 8" help="JPG, PNG o WEBP. La primera imagen será la portada."><input type="file" accept="image/jpeg,image/png,image/webp" multiple onChange={e=>{const a=Array.from(e.target.files||[]);if(a.length>8){toast.error('Podés subir hasta ocho imágenes');return}setImages(a)}}/></Field><Field label="Video MP4 (opcional)"><input type="file" accept="video/mp4" disabled={!!videoUrl} onChange={e=>setVideo(e.target.files?.[0]||null)}/></Field><Field label="O enlace de YouTube / Vimeo"><input type="url" disabled={!!video} value={videoUrl} onChange={e=>setVideoUrl(e.target.value)} placeholder="https://www.youtube.com/watch?v=…"/></Field><div className="notice">Los archivos se revisan antes de habilitar sus descargas. Podés guardar el proyecto como borrador mientras lo preparás.</div>{busy&&<div><Progress value={progress}/><p className="muted" style={{marginTop:8,fontSize:12}}>Subiendo archivo: {progress}%</p></div>}<button className="btn btn-primary" onClick={()=>setStep('Precio')}>Continuar con precio<ArrowRight size={15}/></button></div></TabsContent><TabsContent value="Precio"><div className="panel stack" style={{marginTop:15}}><h2>Vos elegís cómo compartirlo</h2><Field label="Modalidad"><Choice value={data.pricing} onChange={v=>set('pricing',v)} options={['Gratis','Pago']} label="Modalidad"/></Field>{data.pricing==='Pago'&&<Field label="Precio en USD"><input type="number" min="0.01" step="0.01" max="100000" value={data.price} onChange={e=>set('price',e.target.value)}/></Field>}<div className="notice">{deletionNotice}</div><p className="muted" style={{fontSize:14,lineHeight:1.7}}>La propiedad intelectual sigue siendo tuya. La plataforma no vende, cede, licencia ni redistribuye tu contenido a terceros. El acceso administrativo está limitado a los fines de los Términos y Condiciones.</p><label className="checkrow"><Checkbox checked={!!data.accepted} onCheckedChange={v=>set('accepted',v===true)}/><span>Declaro que puedo publicar estos archivos y acepto los <a href="/terminos" style={{textDecoration:'underline'}}>Términos y Condiciones</a>.</span></label><button className="btn btn-primary" disabled={busy||!data.accepted||!requiredFilled||(!file&&!savedAssets.some(a=>a.purpose==='main'&&a.status==='CLEAN'))||(!images.length&&!savedAssets.some(a=>a.purpose==='image'&&a.status==='CLEAN'))||(data.pricing==='Pago'&&price<=0)} onClick={()=>save(true)}>Publicar proyecto<ArrowUpRight size={16}/></button></div></TabsContent></Tabs></div><aside className="stack sticky-panel"><div className="panel stack"><h2>Tu proyecto, en números</h2><div className="row"><span className="muted">Precio de venta</span><strong>{money(price)}</strong></div><div className="row"><span className="muted">Comisión {rate!==null?`(${rate}%)`:''}</span><strong>{rate!==null?money(fee):'Por configurar'}</strong></div><div className="divider"/><div className="row"><strong>Recibís</strong><strong style={{color:'#9adeb9',fontSize:25}}>{money(price-fee)}</strong></div><p className="muted" style={{fontSize:12,lineHeight:1.7}}>El saldo se libera después de {config.retentionDays} días, salvo retenciones por disputas. Los gastos de PayPal los absorbe la plataforma.</p></div><button className="btn" disabled={busy||config.preview||!data.title} onClick={()=>save(false)}>Guardar borrador</button>{!user&&<div className="notice">Podés recorrer el formulario. Para guardarlo o publicar, necesitás <a href="/ingresar" style={{textDecoration:'underline'}}>iniciar sesión</a>.</div>}</aside></div></div>;
}

function Auth({path,config,user,onUser}:{path:string;config:Config;user:User|null;onUser:(u:User|null)=>void}){
 const register=path==='/registro';const [email,setEmail]=useState(''),[password,setPassword]=useState(''),[name,setName]=useState(''),[code,setCode]=useState(''),[busy,setBusy]=useState(false),[setup,setSetup]=useState<any>(null),[message,setMessage]=useState(''),[agree,setAgree]=useState(false),[stage,setStage]=useState('');
 const act=async(e:FormEvent)=>{e.preventDefault();setBusy(true);try{if(path==='/verificar-email'){const token=new URLSearchParams(location.search).get('token');await api('/auth/verify-email','POST',{token});setMessage('Email verificado. Ya podés ingresar.');return}if(path==='/recuperar'){const token=new URLSearchParams(location.search).get('token');await api(token?'/auth/reset-password':'/auth/forgot-password','POST',token?{token,password}:{email});setMessage(token?'Contraseña actualizada. Volvé a ingresar.':'Si el email está registrado, recibirás instrucciones para recuperar tu cuenta.');return}if(stage||path==='/seguridad'){const r=await api(setup?'/auth/totp/confirm':'/auth/totp/verify','POST',{code});if(r.recoveryCodes){setSetup({...setup,recoveryCodes:r.recoveryCodes});setMessage('Guardá estos códigos de recuperación fuera de la plataforma. Se muestran una sola vez.');return}onUser(r.user);location.href=r.user?.role==='CREATOR'?'/creador':'/biblioteca';return}const r=await api(register?'/auth/register':'/auth/login','POST',register?{email,password,name,acceptedTerms:agree}:{email,password});if(register){setMessage('Revisá tu email para verificar la cuenta.');return}onUser(r.user);if(r.stage==='totp_setup'){setStage(r.stage);setSetup(await api('/auth/totp/setup','POST'));return}if(r.stage==='totp'){setStage(r.stage);return}location.href=r.user?.role==='CREATOR'?'/creador':'/biblioteca'}catch(e:any){toast.error(e.message)}finally{setBusy(false)}};
 return <div className="auth-panel panel stack"><div className="eyebrow"><Lock size={15}/>TU ESPACIO EN NEXO</div><h1>{register?'Empezá a crear conexiones.':path==='/verificar-email'?'Verificá tu email':path==='/recuperar'?'Recuperá tu cuenta':stage||path==='/seguridad'?'Protegé tu cuenta':'Qué bueno verte de nuevo.'}</h1><form className="stack" onSubmit={act}>{!stage&&path!=='/seguridad'&&path!=='/verificar-email'&&<>{register&&<Field label="Nombre público"><input value={name} onChange={e=>setName(e.target.value)} autoComplete="name" required minLength={2} maxLength={80}/></Field>}<Field label="Email"><input type="email" value={email} onChange={e=>setEmail(e.target.value)} autoComplete="email" required/></Field>{<Field label="Contraseña" help={register?'Usá al menos 12 caracteres.':undefined}><input type="password" value={password} onChange={e=>setPassword(e.target.value)} autoComplete={register?'new-password':'current-password'} required minLength={register||path==='/recuperar'?12:1}/></Field>}</>}{(stage||path==='/seguridad')&&<>{setup&&!setup.recoveryCodes&&<div className="notice"><strong>Agregá esta cuenta a tu app autenticadora</strong><p>Clave de configuración manual:</p><code style={{wordBreak:'break-all'}}>{setup.secret}</code></div>}{setup?.recoveryCodes?<div className="notice"><p>{message}</p>{setup.recoveryCodes.map((c:string)=><p key={c}><code>{c}</code></p>)}<a className="btn btn-primary" href="/creador">Ya guardé los códigos</a></div>:<Field label="Código de autenticación"><input value={code} onChange={e=>setCode(e.target.value)} autoComplete="one-time-code" inputMode="numeric" required placeholder="000000"/></Field>}</>}{register&&<label className="checkrow"><Checkbox checked={agree} onCheckedChange={v=>setAgree(v===true)}/><span>Acepto los <a href="/terminos" style={{textDecoration:'underline'}}>Términos</a> y leí la <a href="/privacidad" style={{textDecoration:'underline'}}>Política de Privacidad</a>.</span></label>}{!setup?.recoveryCodes&&<button className="btn btn-primary" type="submit" disabled={busy||config.preview||(register&&!agree)}>{busy?'Un momento…':register?'Crear cuenta':path==='/verificar-email'?'Verificar email':path==='/recuperar'?'Enviar instrucciones':stage?'Verificar código':'Ingresar'}<ArrowRight size={16}/></button>}</form>{message&&!setup?.recoveryCodes&&<div className="notice" role="status">{message}</div>}{config.preview&&<p className="notice">Los registros y el acceso se habilitarán al conectar el servidor. No ingreses contraseñas reales en esta vista previa.</p>}<div className="row" style={{fontSize:14}}><a href={register?'/ingresar':'/registro'}>{register?'Ya tengo una cuenta':'Crear una cuenta'}</a><a href="/recuperar" className="muted">Olvidé mi contraseña</a></div></div>;
}

function LibraryPage({user,config}:{user:User|null;config:Config}){const [items,setItems]=useState<any[]>([]);useEffect(()=>{if(user&&!config.preview)api('/library').then(r=>setItems(r.items)).catch(e=>toast.error(e.message))},[user,config.preview]);return <div className="page"><div className="page-heading"><h1>Tu biblioteca</h1><p className="muted">Tus proyectos, en un solo lugar. Descargalos y guardá una copia en tu equipo.</p></div><div className="notice" style={{marginBottom:25}}>{deletionNotice}</div>{!user?<Empty title="Tus próximas ideas te esperan" text="Ingresá para ver tus compras y descargas gratuitas." action="Ingresar" href="/ingresar"/>:items.length?<div className="stack">{items.map(i=><div className="panel row" key={i.id}><div><h2>{i.title}</h2><p className="muted">{i.deleted?'Proyecto eliminado · Archivo no disponible':i.revoked_at?'Acceso revocado':'Guardá una copia local después de descargar.'}</p></div><button className="btn btn-primary" disabled={i.deleted||i.revoked_at} onClick={async()=>{try{const r=await api('/library/'+i.id+'/download','POST');location.href=r.url}catch(e:any){toast.error(e.message)}}}><Download size={16}/>Descargar</button></div>)}</div>:<Empty title="El comienzo de algo grande" text="Cuando obtengas un proyecto, aparecerá acá." action="Explorar proyectos" href="/"/>}</div>}

function WalletPage({user,config}:{user:User|null;config:Config}){
 const [wallet,setWallet]=useState<any>({pending:0,available:0,withdrawn:0,reserved:0,sales:[],withdrawals:[]}),[currency,setCurrency]=useState('USD'),[open,setOpen]=useState(false),[amount,setAmount]=useState(''),[bank,setBank]=useState(''),[holder,setHolder]=useState(''),[tax,setTax]=useState(''),[saveBank,setSaveBank]=useState(false),[busy,setBusy]=useState(false);
 const refresh=()=>{if(user&&!config.preview)api('/wallet?currency='+currency).then(setWallet).catch(e=>toast.error(e.message))};useEffect(refresh,[user,currency,config.preview]);
 return <div className="page"><div className="page-heading row"><div><h1>Mi saldo</h1><p className="muted">Todo lo que generás, con cuentas claras.</p></div><div className="toolbar"><Choice value={currency} onChange={setCurrency} options={['USD','ARS']} label="Moneda"/><button className="btn btn-primary" onClick={()=>setOpen(true)} disabled={!user||config.preview}>Retirar dinero<ArrowUpRight size={16}/></button></div></div><div className="metric-grid">{[['Saldo pendiente',wallet.pending,`Se libera después de ${config.retentionDays} días`],['Saldo disponible',wallet.available,'Listo para solicitar un retiro'],['Total retirado',wallet.withdrawn,'Tus retiros pagados hasta hoy']].map(([label,value,help])=><div className="panel" key={String(label)}><p>{label}</p><strong className="amount">{money(Number(value),currency)}</strong><p style={{fontSize:12,margin:'13px 0 0'}}>{help}</p></div>)}</div><div className="panel row" style={{marginTop:20}}><span className="muted"><Clock size={15} style={{display:'inline',marginRight:8}}/>En solicitudes de retiro</span><strong>{money(wallet.reserved,currency)}</strong></div><div className="notice" style={{margin:'22px 0'}}>Antes del primer retiro, verificaremos tu identidad y que la cuenta sea tuya. No se permiten cuentas de terceros.{currency==='USD'&&' Para retirar USD necesitás una cuenta verificada que reciba dólares.'}</div>{!user?<Empty title="Tus ventas empiezan acá" text="Ingresá como vendedor para consultar tu saldo y verificar tu identidad." action="Ingresar" href="/ingresar" icon={Wallet}/>:<><IdentityForm config={config}/><Tabs defaultValue="Ventas" style={{marginTop:25}}><TabsList><TabsTrigger value="Ventas">Ventas y liberaciones</TabsTrigger><TabsTrigger value="Retiros">Historial de retiros</TabsTrigger></TabsList><TabsContent value="Ventas"><DataTable rows={wallet.sales} columns={['project_title','gross','net','release_at','status']}/></TabsContent><TabsContent value="Retiros"><DataTable rows={wallet.withdrawals} columns={['created_at','amount','currency','status','reason']}/></TabsContent></Tabs></>}<Dialog open={open} onOpenChange={setOpen}><DialogContent><DialogTitle>Retirar dinero</DialogTitle><DialogDescription>Disponible: {money(wallet.available,currency)} · Mínimo: {money(config.minimumWithdrawals[currency]||0,currency)}</DialogDescription><form className="stack" onSubmit={async e=>{e.preventDefault();setBusy(true);try{await api('/withdrawals','POST',{currency,amount:Math.round(Number(amount)*100),account:bank,holder,taxId:tax,saveAccount:saveBank,idempotencyKey:crypto.randomUUID()});setOpen(false);refresh();toast.success('Tu solicitud fue recibida. La transferencia puede demorar hasta 24 horas hábiles.')}catch(e:any){toast.error(e.message)}finally{setBusy(false)}}}><Field label={`Monto (${currency})`}><input type="number" value={amount} onChange={e=>setAmount(e.target.value)} min={(config.minimumWithdrawals[currency]||1)/100} max={wallet.available/100} step="0.01" required/></Field><Field label="CBU / CVU o alias"><input value={bank} onChange={e=>setBank(e.target.value)} required/></Field><Field label="Nombre completo del titular"><input value={holder} onChange={e=>setHolder(e.target.value)} required/></Field><Field label="CUIL / CUIT del titular"><input value={tax} onChange={e=>setTax(e.target.value)} required/></Field><label className="checkrow"><Checkbox checked={saveBank} onCheckedChange={v=>setSaveBank(v===true)}/>Guardar esta cuenta</label><button className="btn btn-primary" disabled={busy||config.preview}>Confirmar solicitud</button></form></DialogContent></Dialog></div>;
}
function IdentityForm({config}:{config:Config}){
 const [open,setOpen]=useState(false),[tax,setTax]=useState(''),[name,setName]=useState(''),[files,setFiles]=useState<Record<string,File>>({}),[busy,setBusy]=useState(false),[progress,setProgress]=useState(0),[message,setMessage]=useState('');
 return <div className="panel"><div className="row"><div><h2>Verificación de identidad</h2><p className="muted" style={{fontSize:14}}>Tu DNI y una selfie se revisan de forma privada.</p></div><button className="btn" onClick={()=>setOpen(x=>!x)}>Verificar identidad</button></div>{open&&<form className="stack" style={{marginTop:20}} onSubmit={async e=>{e.preventDefault();setBusy(true);try{const frontId=await uploadPrivate(files.identity_front,'identity_front',setProgress);const backId=await uploadPrivate(files.identity_back,'identity_back',setProgress);const selfieId=await uploadPrivate(files.selfie,'selfie',setProgress);await api('/identity-verifications','POST',{fullName:name,taxId:tax,frontId,backId,selfieId});setMessage('Documentos enviados. Tu verificación está pendiente de revisión.');toast.success('Verificación enviada')}catch(e:any){toast.error(e.message)}finally{setBusy(false)}}}><Field label="Nombre completo"><input required value={name} onChange={e=>setName(e.target.value)}/></Field><Field label="CUIL / CUIT"><input required value={tax} onChange={e=>setTax(e.target.value)}/></Field>{[['identity_front','DNI frente'],['identity_back','DNI dorso'],['selfie','Selfie']].map(([k,l])=><Field key={k} label={l}><input required type="file" accept="image/jpeg,image/png" onChange={e=>{if(e.target.files?.[0])setFiles({...files,[k]:e.target.files[0]})}}/></Field>)}<p className="muted" style={{fontSize:12}}>Leé cómo tratamos estos documentos en la Política de Privacidad.</p>{busy&&<Progress value={progress}/>}<button className="btn btn-primary" disabled={config.preview||busy}>{busy?'Subiendo y revisando…':'Enviar a revisión'}</button>{message&&<p className="notice">{message}</p>}</form>}</div>
}

function MyProjects({user,config}:{user:User|null;config:Config}){const [projects,setProjects]=useState<any[]>([]),[del,setDel]=useState<any>(null),[confirm,setConfirm]=useState('');const refresh=()=>{if(user&&!config.preview)api('/seller/projects').then(r=>setProjects(r.projects)).catch(e=>toast.error(e.message))};useEffect(refresh,[user,config.preview]);return <div className="page"><div className="page-heading row"><div><h1>Mis proyectos</h1><p className="muted">Tus ideas publicadas y las que todavía estás preparando.</p></div><a className="btn btn-primary" href="/publicar"><Plus size={16}/>Nuevo proyecto</a></div>{projects.length?<div className="stack">{projects.map(p=><div className="panel row" key={p.id}><div><h2>{p.title}</h2><span className="status-text">{p.publication_status}</span></div><div className="toolbar"><a className="btn" href={'/publicar?edit='+p.id}>Editar proyecto</a><button className="btn" onClick={async()=>{try{await api('/seller/projects/'+p.id+'/unpublish','POST');refresh()}catch(e:any){toast.error(e.message)}}}>Despublicar</button><button className="btn" onClick={()=>{setDel(p);setConfirm('')}}><Trash2 size={16}/>Eliminar</button></div></div>)}</div>:<Empty title="Dale lugar a tu primera idea" text="Los proyectos que publiques o guardes como borrador aparecerán acá." action={user?'Publicar proyecto':'Ingresar'} href={user?'/publicar':'/ingresar'} icon={UploadCloud}/>}<Dialog open={!!del} onOpenChange={v=>!v&&setDel(null)}><DialogContent><DialogTitle>Eliminar proyecto y archivos</DialogTitle><DialogDescription>Esta acción impide nuevas descargas y elimina las copias almacenadas. Quienes ya compraron perderán la posibilidad de volver a descargar. No se puede deshacer.</DialogDescription><Field label="Escribí ELIMINAR para confirmar"><input value={confirm} onChange={e=>setConfirm(e.target.value)}/></Field><button className="btn" style={{color:'#ff969f'}} disabled={confirm!=='ELIMINAR'} onClick={async()=>{try{await api('/seller/projects/'+del.id,'DELETE',{confirmation:'ELIMINAR'});setDel(null);refresh();toast.success('Proyecto retirado. Se inició la eliminación definitiva de sus archivos.')}catch(e:any){toast.error(e.message)}}}>Eliminar definitivamente</button></DialogContent></Dialog></div>}

function DataTable({rows,columns}:{rows:any[];columns:string[]}){if(!rows?.length)return <div className="empty-state" style={{padding:32,marginTop:16}}><p style={{margin:0}}>No hay movimientos para mostrar.</p></div>;const names:Record<string,string>={created_at:'Fecha',project_title:'Proyecto',gross:'Bruto',net:'Neto',release_at:'Se libera',status:'Estado',amount:'Monto',currency:'Moneda',reason:'Motivo',email:'Email',name:'Nombre',role:'Rol',title:'Título',commission:'Comisión',action:'Acción',ip:'IP',id:'ID'};return <div className="table-wrap panel" style={{marginTop:16}}><Table><TableHeader><TableRow>{columns.map(k=><TableHead key={k}>{names[k]||k}</TableHead>)}</TableRow></TableHeader><TableBody>{rows.map((r,i)=><TableRow key={r.id||i}>{columns.map(k=><TableCell key={k}>{['gross','net','amount','commission'].includes(k)?money(Number(r[k]),r.currency):typeof r[k]==='object'?JSON.stringify(r[k]):String(r[k]??'—')}</TableCell>)}</TableRow>)}</TableBody></Table></div>}

function Admin({user,config}:{user:User|null;config:Config}){
 const [tab,setTab]=useState('Dashboard'),[rows,setRows]=useState<any[]>([]),[dashboard,setDashboard]=useState<any>({}),[form,setForm]=useState<Record<string,any>>({}),[target,setTarget]=useState<any>(null),[reason,setReason]=useState(''),[operation,setOperation]=useState(''),[receipt,setReceipt]=useState<File|null>(null),[payBusy,setPayBusy]=useState(false);
 const sections=['Dashboard','Retiros','Finanzas','Usuarios','Verificaciones','Cuentas bancarias','Proyectos','Moderación','Marketing','Estadísticas','Configuración','Seguridad'];
 const paths:Record<string,string>={Retiros:'withdrawals',Finanzas:'transactions',Usuarios:'users',Verificaciones:'verifications','Cuentas bancarias':'bank-accounts',Proyectos:'projects',Moderación:'reports',Marketing:'campaigns',Estadísticas:'statistics',Configuración:'settings',Seguridad:'audit'};
 const refresh=()=>{if(user?.role!=='CREATOR'||config.preview)return;api('/admin/'+(paths[tab]||'dashboard')).then(r=>{setRows(r.items||[]);if(tab==='Dashboard')setDashboard(r);if(tab==='Configuración')setForm(r.settings||{})}).catch(e=>toast.error(e.message))};useEffect(refresh,[tab,user,config.preview]);
 if(user?.role!=='CREATOR')return <div className="page"><Empty title="Espacio del CREADOR" text="Acceso protegido con contraseña y autenticación de dos factores." action="Ingresar de forma segura" href="/ingresar" icon={ShieldCheck}/></div>;
 return <div className="page"><div className="page-heading"><div className="eyebrow"><ShieldCheck size={15}/>ADMINISTRACIÓN</div><h1>Todo tu marketplace, a mano.</h1></div><Tabs value={tab} onValueChange={setTab}><TabsList style={{maxWidth:'100%',overflowX:'auto',justifyContent:'start',height:45}}>{sections.map(s=><TabsTrigger key={s} value={s}>{s}</TabsTrigger>)}</TabsList><div style={{marginTop:23}}>{tab==='Dashboard'?<><div className="metric-grid">{[['Ventas USD',dashboard.salesUsd||0],['Comisiones USD',dashboard.commissionsUsd||0],['Saldo de vendedores USD',dashboard.sellerLiabilityUsd||0]].map(([k,v])=><div className="panel" key={String(k)}><p>{k}</p><strong className="amount">{money(Number(v))}</strong></div>)}</div><div className="metric-grid" style={{marginTop:20}}>{[['Retiros pendientes',dashboard.pendingWithdrawals||0],['Verificaciones',dashboard.pendingVerifications||0],['Reportes',dashboard.pendingReports||0]].map(([k,v])=><div className="panel" key={String(k)}><p>{k}</p><strong className="amount">{v}</strong></div>)}</div></>:tab==='Configuración'?<div className="panel stack"><h2>Configuración de la plataforma</h2><div className="field-grid">{[['retentionDays','Días de retención'],['maxFileMB','Tamaño máximo (MB)'],['minimumWithdrawalUsd','Retiro mínimo USD (centavos)'],['commissionBelowUsd','Comisión USD bajo umbral (%)'],['commissionAboveUsd','Comisión USD desde umbral (%)'],['thresholdUsd','Umbral USD (centavos)']].map(([k,label])=><Field key={k} label={label}><input type="number" value={form[k]??''} onChange={e=>setForm({...form,[k]:Number(e.target.value)})}/></Field>)}</div><label className="checkrow"><Checkbox checked={!!form.requireApproval} onCheckedChange={v=>setForm({...form,requireApproval:v===true})}/>Requerir aprobación de nuevos proyectos</label><label className="checkrow"><Checkbox checked={!!form.maintenance} onCheckedChange={v=>setForm({...form,maintenance:v===true})}/>Modo mantenimiento</label><button className="btn btn-primary" onClick={async()=>{try{await api('/admin/settings','PATCH',form);toast.success('Configuración actualizada')}catch(e:any){toast.error(e.message)}}}>Guardar cambios</button></div>:<><div className="row"><h2 className="section-title">{tab}</h2>{['Finanzas','Retiros'].includes(tab)&&<div className="toolbar"><a className="btn" href={'/api/v1/admin/'+paths[tab]+'/export'}><Download size={15}/>CSV</a><a className="btn" href={'/api/v1/admin/'+paths[tab]+'/export?format=xlsx'}><Download size={15}/>Excel</a></div>}</div>{tab==='Retiros'?<div className="stack" style={{marginTop:20}}>{rows.length?rows.map(r=><div className="panel stack" key={r.id}><div className="row"><strong>{r.seller_name} · {money(r.amount,r.currency)}</strong><span className="status-text">{r.status}</span></div><p className="muted">Solicitud: {new Date(r.created_at).toLocaleString('es-AR')} · Vence: {new Date(r.due_at).toLocaleString('es-AR')}</p>{Object.entries(r.bank||{}).map(([k,v])=><div className="row" key={k}><span>{k}: {String(v)}</span><button className="icon-btn" aria-label={'Copiar '+k} onClick={()=>{navigator.clipboard.writeText(String(v));toast.success('Copiado')}}><Copy size={14}/></button></div>)}<div className="toolbar"><button className="btn" disabled={r.status!=='PENDING'} onClick={async()=>{try{await api('/admin/withdrawals/'+r.id+'/take','POST');refresh()}catch(e:any){toast.error(e.message)}}}>Tomar</button><button className="btn" onClick={()=>setTarget(r)}>Resolver</button></div></div>):<Empty title="No hay retiros pendientes" text="Las solicitudes aparecerán ordenadas por antigüedad." icon={Wallet}/>}</div>:<DataTable rows={rows} columns={tab==='Usuarios'?['email','name','role','status']:tab==='Finanzas'?['created_at','gross','commission','net','currency','status']:tab==='Seguridad'?['created_at','action','target_id','ip']:tab==='Proyectos'?['id','title','publication_status']:['id','created_at','status','reason']}/>}</>}</div><AdminManager section={tab} rows={rows} refresh={refresh}/></Tabs><Dialog open={!!target} onOpenChange={v=>!v&&setTarget(null)}><DialogContent><DialogTitle>Resolver retiro</DialogTitle><DialogDescription>Confirmá la transferencia solo después de realizarla y adjuntar el comprobante.</DialogDescription><Field label="Número de operación"><input value={operation} onChange={e=>setOperation(e.target.value)}/></Field><Field label="Comprobante de transferencia"><input type="file" accept="image/jpeg,image/png,application/pdf" onChange={e=>setReceipt(e.target.files?.[0]||null)}/></Field><button className="btn btn-primary" disabled={!receipt||operation.trim().length<3||payBusy||target?.status!=='PROCESSING'} onClick={async()=>{setPayBusy(true);try{const receiptId=await uploadPrivate(receipt!,'receipt');await api('/admin/withdrawals/'+target.id+'/paid','POST',{operationNumber:operation,receiptId});setTarget(null);refresh();toast.success('Retiro registrado como pagado')}catch(e:any){toast.error(e.message)}finally{setPayBusy(false)}}}>{payBusy?'Verificando comprobante…':'Marcar pagado'}</button><Field label="Motivo de rechazo"><textarea value={reason} onChange={e=>setReason(e.target.value)}/></Field><button className="btn" disabled={reason.trim().length<5} onClick={async()=>{try{await api('/admin/withdrawals/'+target.id+'/reject','POST',{reason});setTarget(null);refresh()}catch(e:any){toast.error(e.message)}}}>Rechazar y devolver saldo</button></DialogContent></Dialog></div>;
}
function Seller({id,config}:{id:string;config:Config}){const [seller,setSeller]=useState<any>(null),[projects,setProjects]=useState<Project[]>([]);useEffect(()=>{if(config.preview){setSeller({name:'Creadores Nexo',bio:'Perfiles de muestra para explorar el marketplace.',verified:false});setProjects(demoProjects)}else api('/sellers/'+id).then(r=>{setSeller(r.seller);setProjects(r.projects)}).catch(e=>toast.error(e.message))},[id,config.preview]);return <div className="page"><div className="panel page-heading"><div className="eyebrow">PERFIL DEL VENDEDOR</div><h1>{seller?.name||'Vendedor'}</h1><p className="muted">{seller?.bio}</p>{seller?.verified&&<p style={{color:'#83d4b3',marginTop:12}}>✓ Vendedor verificado</p>}</div><h2 className="section-title" style={{marginBottom:20}}>Proyectos publicados</h2><div className="project-grid">{projects.map(p=><Card p={p} key={p.id}/>)}</div></div>}
function CopyrightForm({config}:{config:Config}){const [form,setForm]=useState({name:'',email:'',projectUrl:'',originalUrl:'',description:'',declaration:false});return <div className="page legal"><h1>Denunciar una infracción de derechos de autor</h1><p>Si un proyecto utiliza una obra tuya sin autorización, describí la situación y aportá evidencia para que podamos revisarla.</p><form className="panel stack" onSubmit={async e=>{e.preventDefault();try{await api('/copyright-claims','POST',form);toast.success('Denuncia recibida para revisión');setForm({...form,description:''})}catch(e:any){toast.error(e.message)}}}>{[['name','Nombre completo'],['email','Email de contacto'],['projectUrl','URL del proyecto denunciado'],['originalUrl','Enlace a tu obra o evidencia']].map(([k,l])=><Field label={l} key={k}><input required type={k==='email'?'email':k.endsWith('Url')?'url':'text'} value={(form as any)[k]} onChange={e=>setForm({...form,[k]:e.target.value})}/></Field>)}<Field label="Descripción de la infracción"><textarea required minLength={30} maxLength={10000} value={form.description} onChange={e=>setForm({...form,description:e.target.value})}/></Field><label className="checkrow"><Checkbox checked={form.declaration} onCheckedChange={v=>setForm({...form,declaration:v===true})}/>Declaro de buena fe que soy titular o representante autorizado y que la información es correcta.</label><button className="btn btn-primary" disabled={config.preview||!form.declaration}>Enviar denuncia</button>{config.preview&&<p className="notice">Este formulario se habilitará con el servidor. No envía denuncias en la vista previa.</p>}</form></div>}
function PaymentResult({user}:{user:User|null}){const [message,setMessage]=useState('Verificando el estado del pago…');useEffect(()=>{const params=new URLSearchParams(location.search),token=params.get('token');if(params.get('cancelled')){setMessage('Cancelaste el pago. No se habilitó una compra.');return}if(!token){setMessage('Consultá el estado de tus compras en tu biblioteca.');return}api('/payments/paypal/capture','POST',{orderId:token}).then(()=>setMessage('La captura fue solicitada. Tu proyecto aparecerá en la biblioteca cuando PayPal confirme el pago por webhook.')).catch(e=>setMessage(e.message))},[]);return <div className="page"><Empty title="Estado de tu compra" text={message} action="Ver mi biblioteca" href="/biblioteca" icon={ShieldCheck}/></div>}
